#include <cmath>
#include <algorithm>
#include <cstring>
extern "C" {
void render(float* pts,int n,float* out,int H,int W,float scale) {
 memset(out,0,H*W*sizeof(float));
 // Rasterize brush-root path, using smooth Catmull-Rom centerline, linear width.
 for(int k=0;k<n-1;k++) {
  float *a=pts+3*std::max(0,k-1),*b=pts+3*k,*c=pts+3*(k+1),*d=pts+3*std::min(n-1,k+2);
  int ns=std::max(2,(int)ceil(hypot(c[0]-b[0],c[1]-b[1])*1.5));
  for(int j=0;j<=ns;j++) {
   float t=float(j)/ns;float q[3],v[2];
   for(int z=0;z<3;z++) {
    float A=2*b[z],B=-a[z]+c[z],C=2*a[z]-5*b[z]+4*c[z]-d[z],D=-a[z]+3*b[z]-3*c[z]+d[z];
    q[z]=0.5f*(A+B*t+C*t*t+D*t*t*t);
    if(z<2)v[z]=0.5f*(B+2*C*t+3*D*t*t);
   }
   float len=hypot(v[0],v[1]);if(len<1e-5)continue;
   float ex=v[0]/len,ey=v[1]/len;float w=std::max(.1f,q[2])*scale;
   // millimeters per pixel 0.22185987; d = 1.075*(w_mm+.3)/1.187+1.38
   float drag=(1.075f*(std::max(.1f,q[2])*.22185987f+.3f)/1.187f+1.38f)/.22185987f*scale;
   float x=q[0]*scale,y=q[1]*scale;
   int x0=std::max(0,(int)floor(x-std::max(0.f,drag*ex)-fabs(ey*w/2)-2));
   int x1=std::min(W-1,(int)ceil(x-std::min(0.f,drag*ex)+fabs(ey*w/2)+2));
   int y0=std::max(0,(int)floor(y-std::max(0.f,drag*ey)-fabs(ex*w/2)-2));
   int y1=std::min(H-1,(int)ceil(y-std::min(0.f,drag*ey)+fabs(ex*w/2)+2));
   for(int r=y0;r<=y1;r++)for(int c=x0;c<=x1;c++) {
    float dx=c-x,dy=r-y,s=-(dx*ex+dy*ey),u=-dx*ey+dy*ex;
    float f=drag*(1-4*u*u/(w*w))-s;
    float sd=std::min(s,f/sqrt(1+pow(8*drag*u/(w*w),2)));
    float cov=std::min(1.f,std::max(0.f,sd+.5f));
    out[r*W+c]=std::max(out[r*W+c],cov);
   }
  }
 }
}
}
